        print(f"Error loading GSL libraries: {e}")
        return None

    # Get the type of random number generator from the name
    rng_type = gsl.gsl_rng_type_from_name(rng_name)
    if not rng_type:
        print(f"Invalid RNG name: {rng_name}")
        return None

    # Allocate the random number generator
    try:
        rng = gsl.gsl_rng_alloc(rng_type)
    except RuntimeError as e:
        print(f"Error allocating RNG: {e}")
        return None

    # Return a ctypes pointer to the allocated structure
    return ctypes.pointer(rng)

