    gsl_linalg_LU_decomp_func = libcblas.gsl_linalg_LU_decomp
    gsl_linalg_LU_decomp_func.argtypes = [ctypes.POINTER(gsl.gsl_matrix)]
    gsl_linalg_LU_decomp_func.restype = ctypes.c_int

