class GSLMatrix:
    def __init__(self, n1, n2):
        self.n1 = n1
        self.n2 = n2
        self.ptr = gsl.gsl_matrix(n1, n2)

    def set(self, matrix):
        for i in range(self.n1):
            for j in range(self.n2):
                self.ptr[i, j] = matrix[i][j]

    def get(self):
        result = []
        for i in range(self.n1):
            row = []
            for j in range(self.n2):
                row.append(self.ptr[i, j])
            result.append(row)
        return result

class GSLPermutation:
    def __init__(self, n):
        self.n = n
        self.ptr = gsl.gsl_permutation(n)

    def set(self, perm):
        for i in range(self.n):
            self.ptr[i] = perm[i]

    def get(self):
        return [self.ptr[i] for i in range(self.n)]

