    return (m.get_array(), p.get_array(), s.value)

class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix
        self.rows = len(matrix)
        self.cols = len(matrix[0]) if len(matrix) > 0 else 0
        self.size = self.rows * self.cols
        self.data = (c_double * self.size)(*itertools.chain.from_iterable(matrix))

    def get_array(self):
        return [[float(x) for x in row] for row in self.data]

