import ctypes
import json

class DotProductError(Exception):
    pass

def cblas_ddot_wrapper(vector_x, vector_y):
    if not isinstance(vector_x, list) or not isinstance(vector_y, list):
        raise DotProductError("Input vectors must be lists")
    if len(vector_x) != len(vector_y):
        raise DotProductError("Input vectors must have the same length")

    gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    cdouble_p = ctypes.POINTER(ctypes.c_double)
    vector_x_ptr = (cdouble_p * len(vector_x))(*vector_x)
    vector_y_ptr = (cdouble_p * len(vector_y))(*vector_y)

    try:
        result = gslcblas.ddot(ctypes.c_int(len(vector_x)), vector_x_ptr, ctypes.c_int(1), vector_y_ptr, ctypes.c_int(1))
    except Exception as e:
        raise DotProductError("Error computing dot product") from e

    return result.value

def compute_dot_product(vector_x, vector_y):
    try:
        result = cblas_ddot_wrapper(vector_x, vector_y)
    except DotProductError as e:
        raise e
    else:
        return result

